const pages=[['novedades.html','NOVEDADES'],['hombre.html','HOMBRE'],['mujer.html','MUJER'],['ninos.html','NIÑOS'],['marcas.html','MARCAS'],['ofertas.html','OFERTAS'],['lanzamientos.html','LANZAMIENTOS'],['editorial.html','EDITORIAL'],['tiendas.html','⌖ TIENDAS']];
const current=location.pathname.split('/').pop()||'index.html';
const searchQuery=(new URLSearchParams(location.search).get('q')||'').replace(/[&<>"]/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[char]));
document.querySelector('#site-header').innerHTML=`<div class="promo">CATÁLOGO DE ZAPATILLAS ACTUALIZADO&nbsp;&nbsp; ✦ &nbsp;&nbsp;JORDAN Y NIKE</div><header class="shop-head"><div class="head-row"><a class="logo" href="index.html" aria-label="Lil David, inicio"><img src="LOGO.png" alt="Lil David"></a><form class="head-search" role="search" action="novedades.html"><label class="sr-only" for="catalog-search">Buscar en el catálogo</label><input id="catalog-search" name="q" type="search" autocomplete="off" placeholder="BUSCAR EN EL CATÁLOGO" value="${searchQuery}"><button type="submit" aria-label="Buscar">⌕</button></form></div><nav class="shop-nav">${pages.map(([u,n])=>`<a href="${u}" class="${current===u?'active':''}">${n}</a>`).join('')}</nav></header>`;
document.querySelector('#site-footer').innerHTML=`<footer class="footer"><a class="footer-logo" href="index.html" aria-label="Lil David, inicio"><img src="LOGO.png" alt="Lil David"></a><div><h3>TIENDA</h3><a href="novedades.html">Novedades</a><a href="hombre.html">Hombre</a><a href="mujer.html">Mujer</a><a href="ninos.html">Niños</a></div><div><h3>AYUDA</h3><a href="tiendas.html">Tiendas</a><a href="#">Envíos y devoluciones</a><a href="#">Contacto</a></div><small>© 2026 LIL DAVID — CONCEPTO DE DEMOSTRACIÓN</small></footer><div class="toast">AÑADIDO A TU LISTA ✓</div>`;
document.querySelectorAll('img[src^="assets/"]').forEach(img=>{const url=new URL(img.src);url.searchParams.set('v','20261030-catalog');img.src=url.href;});
document.querySelectorAll('.heart').forEach(btn=>btn.addEventListener('click',()=>{const t=document.querySelector('.toast');t.classList.add('show');setTimeout(()=>t.classList.remove('show'),1800)}));
document.querySelectorAll('.filter-bar button').forEach(btn=>btn.addEventListener('click',()=>{btn.parentElement.querySelectorAll('button').forEach(x=>x.classList.remove('active'));btn.classList.add('active')}));
if(current==='hombre.html'){const copy=document.querySelector('.split-copy p:not(.kicker)');const link=document.querySelector('.split-copy .btn');if(copy)copy.textContent='Consulta modelos, tallas y precios actualizados en soles.';if(link)link.textContent='VER LOS 36 MODELOS'}
if(current==='ofertas.html'){const notes=document.querySelectorAll('.title-row>p');if(notes[0])notes[0].textContent='TALLAS Y PRECIOS ACTUALIZADOS';if(notes[1])notes[1].textContent='LOS 8 PRECIOS MÁS BAJOS'}
const productShadows=document.createElement('link');productShadows.rel='stylesheet';productShadows.href='product-shadows.css?v=20261111';document.head.append(productShadows);
const searchScript=document.createElement('script');searchScript.src='search.js?v=20261103-contacts';document.head.append(searchScript);
